     1→# ABOUTME: Earley parser implementation with Leo optimization for Chalk
     2→# ABOUTME: Provides EarleyItem, LeoItem, EarleyChart, and Parser classes
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→use Chalk::Semiring::Boolean;
     7→
     8→class Chalk::EarleyItem {
     9→    use overload '""' => 'key';
    10→
    11→    field $start_pos :param :reader;
    12→    field $rule      :param :reader;
    13→    field $dot_pos   :param :reader;
    14→    field $end_pos   :param :reader;
    15→    field $rule_id = $rule->id;
    16→    field @rhs     = $rule->rhs->@*;
    17→    field $complete    :reader = $dot_pos >= scalar(@rhs);
    18→    field $next_symbol :reader = $complete ? '' : $rhs[$dot_pos];
    19→    field $key = "Earley|$start_pos|$rule_id|$dot_pos|$end_pos";
    20→
    21→    method advance_dot() {
    22→        Chalk::EarleyItem->new(
    23→            start_pos => $start_pos,
    24→            rule      => $rule,
    25→            dot_pos   => $dot_pos + 1,
    26→            end_pos   => $end_pos,
    27→        );
    28→    }
    29→
    30→    method key(@) { $key }
    31→}
    32→
    33→# Leo Items: Limited optimization for right-recursive grammar patterns
    34→#
    35→# This is a LIMITED implementation of Joop Leo's optimization (1991) for right-recursive
    36→# grammars.  It creates "Leo items" only in DETERMINISTIC cases where:
    37→# 1. Exactly one Earley item is waiting for the completed symbol
    38→# 2. The waiting item will be complete after this one reduction
    39→# 3. The rule is right-recursive (LHS appears as last RHS symbol)
    40→#
    41→# Why limited? Full Leo would create items even with multiple waiting items and maintain
    42→# a hash lookup by (position, symbol). Our grammar has 41 right-recursive rules, but
    43→# performance testing shows grammar complexity (960+ rules) is the main bottleneck,
    44→# not right-recursion specifically. This limited implementation provides O(n) behavior
    45→# for simple right-recursive chains (ArrowChain, StatementList) without the complexity
    46→# of full Leo.
    47→#
    48→# See t/optimization/test-leo-items.t for verification tests.
    49→# See issue #10 for detailed analysis and rationale.
    50→class Chalk::LeoItem {
    51→    use overload '""' => 'key';
    52→
    53→    field $symbol    :param :reader;
    54→    field $start_pos :param :reader;
    55→    field $end_pos   :param :reader;
    56→    field $top_item  :param :reader;
    57→    field $rule      :reader = $top_item->rule;
    58→
    59→    method complete()    { 1 }
    60→    method next_symbol() { }
    61→
    62→    method key(@) {
    63→        return "LEO:$symbol|$start_pos|$end_pos";
    64→    }
    65→
    66→}
    67→
    68→class Chalk::EarleyChart {
    69→    field $semiring :param;
    70→    field %chart;
    71→    field @by_end_pos;
    72→    field %predicted;    # Track what we've predicted at each position
    73→    field %completed;    # Track what we've completed
    74→    field %waiting_for;  # Index: waiting_for{symbol}{pos} = [items waiting for symbol at pos]
    75→    field %leo_waiting_for;  # Index: leo_waiting_for{symbol}{pos} = [Leo items waiting for symbol at pos]
    76→
    77→    method add_item($earley_item) {
    78→        $chart{ $earley_item->key } = $earley_item;
    79→    }
    80→
    81→    method get_element($key) { $chart{$key} }
    82→
    83→    method add_element( $item, $element ) {
    84→        my $key     = $item->key;
    85→        my $current = $self->get_element($key);
    86→        $chart{$key} = $current ? $current + $element : $element;
    87→
    88→        push( $by_end_pos[ $item->end_pos ]->@*, $item );
    89→
    90→        # Index by what they're waiting for
    91→        if ($item isa Chalk::LeoItem) {
    92→            # Leo items are indexed by their symbol and end position
    93→            my $symbol = $item->symbol;
    94→            push @{$leo_waiting_for{$symbol}{$item->end_pos} //= []}, $item;
    95→        }
    96→        elsif (!$item->complete) {
    97→            # Regular items indexed by next_symbol
    98→            my $next_sym = $item->next_symbol;
    99→            if ($next_sym) {
   100→                push @{$waiting_for{$next_sym}{$item->end_pos} //= []}, $item;
   101→            }
   102→        }
   103→
   104→        return $chart{$key};
   105→    }
   106→
   107→    method items_ending_at($end_pos) {
   108→        return $by_end_pos[$end_pos]->@* if $by_end_pos[$end_pos];
   109→        return;
   110→    }
   111→
   112→    method items_waiting_for($symbol, $pos) {
   113→        return $waiting_for{$symbol}{$pos}->@* if exists($waiting_for{$symbol}{$pos});
   114→        return;
   115→    }
   116→
   117→    method leo_items_waiting_for($symbol, $pos) {
   118→        return $leo_waiting_for{$symbol}{$pos}->@* if exists($leo_waiting_for{$symbol}{$pos});
   119→        return;
   120→    }
   121→
   122→    method has_item($item) {
   123→        return exists( $chart{$item} );
   124→    }
   125→
   126→    method has_predicted( $nonterminal, $pos, $rule_id ) {
   127→        return exists( $predicted{"$nonterminal|$pos|$rule_id"} );
   128→    }
   129→
   130→    method mark_predicted( $nonterminal, $pos, $rule_id ) {
   131→        $predicted{"$nonterminal|$pos|$rule_id"} = 1;
   132→    }
   133→
   134→    method has_completed($item) {
   135→        return exists( $completed{$item} );
   136→    }
   137→
   138→    method mark_completed($item) {
   139→        $completed{$item} = 1;
   140→    }
   141→
   142→    method goal_value( $start_symbol, $n ) {
   143→
   144→        # Find all complete items that span [0,n] with LHS = start_symbol
   145→        my $result = $semiring->add_id;
   146→
   147→        my @items = $self->items_ending_at($n);
   148→
   149→        for my $item (@items) {
   150→            next unless $item->complete;
   151→            next unless $item->start_pos == 0;
   152→            next unless $item->rule->lhs eq $start_symbol;
   153→
   154→            my $element = $self->get_element($item);
   155→            if ($element) {
   156→                $result = $result + $element;
   157→            }
   158→        }
   159→
   160→        # Check if we found any valid parses
   161→        return $result == $semiring->add_id ? undef : $result;
   162→    }
   163→}
   164→
   165→class Chalk::Parser {
   166→    field $semiring :param = Chalk::Semiring::Boolean->new();
   167→    field $grammar :param;
   168→    field $preprocess :param = [];  # Arrayref of preprocessor class names
   169→
   170→    method parse_string($input_string) {
   171→        # Apply preprocessors in sequence
   172→        for my $preprocessor_class (@$preprocess) {
   173→            next unless defined $preprocessor_class;
   174→
   175→            # Load the preprocessor module
   176→            (my $file = $preprocessor_class) =~ s|::|/|g;
   177→            require "$file.pm";
   178→
   179→            # Apply preprocessing
   180→            my $preprocessor = $preprocessor_class->new(input => $input_string);
   181→            $preprocessor->transform();
   182→            $input_string = $preprocessor->output;
   183→        }
   184→
   185→        my $chart = Chalk::EarleyChart->new( semiring => $semiring );
   186→
   187→       # Initialize chart by predicting all rules for start symbol at position 0
   188→        my $start_symbol = $grammar->start_symbol;
   189→        for my $rule ( $grammar->rules_for($start_symbol) ) {
   190→            my $start_item = Chalk::EarleyItem->new(
   191→                start_pos => 0,
   192→                rule      => $rule,
   193→                dot_pos   => 0,
   194→                end_pos   => 0,
   195→            );
   196→
   197→            my $start_element = $semiring->init_element_from_rule($rule, 0, 0);
   198→            $chart->add_element( $start_item, $start_element );
   199→        }
   200→
   201→        # Process positions from 0 to end of string
   202→        my $pos             = 0;
   203→        my $input_length    = length($input_string);
   204→        my $last_active_pos = 0;
   205→
   206→        while ( $pos <= $input_length ) {
   207→            my @agenda_before = $chart->items_ending_at($pos);
   208→            $self->process_position_string( $pos, $chart, $input_string );
   209→
   210→            # Track the last position where we had active items
   211→            if ( @agenda_before > 0 ) {
   212→                $last_active_pos = $pos;
   213→            }
   214→
   215→            ++$pos;
   216→        }
   217→
   218→        my $result =
   219→          $chart->goal_value( $grammar->start_symbol, $input_length );
   220→
   221→        # Show where parsing actually stopped if it failed
   222→        if ( !$result && $last_active_pos < $input_length ) {
   223→            warn(
   224→"🔍 PARSING STOPPED: Reached position $last_active_pos of $input_length ("
   225→                  . sprintf( "%.1f", 100 * $last_active_pos / $input_length )
   226→                  . "%)\n" );
   227→        }
   228→
   229→        return $result;
   230→    }
   231→
   232→    method process_position_string( $pos, $chart, $input_string ) {
   233→        my @agenda = $chart->items_ending_at($pos);
   234→
   235→        while ( my $item = shift(@agenda) ) {
   236→            my $element = $chart->get_element($item);
   237→            next unless defined($element);
   238→
   239→            if ( $item->complete ) {
   240→                $self->complete( $item, $element, $chart, \@agenda );
   241→            }
   242→            elsif ( defined( my $next_sym = $item->next_symbol ) ) {
   243→                if ( $grammar->is_nonterminal($next_sym) ) {
   244→                    $self->predict( $item, $next_sym, $chart, \@agenda );
   245→                }
   246→                else {
   247→                    # Try to match terminal with lexeme support
   248→                    my $pattern = $item->rule->terminal_to_regex($next_sym);
   249→                    pos($input_string) = $pos;
   250→                    if ( $input_string =~ /\G($pattern)/gc ) {
   251→                        my $match_length = length($1);
   252→                        $self->scan( $item, $element, $chart, $pos,
   253→                            $match_length );
   254→                    }
   255→                }
   256→            }
   257→        }
   258→    }
   259→
   260→    method complete( $completed_item, $completed_element, $chart, $agenda ) {
   261→
   262→        # Check if we've already completed this item
   263→        return if $chart->has_completed($completed_item);
   264→        $chart->mark_completed($completed_item);
   265→
   266→        my $lhs = $completed_item->rule->lhs;
   267→
   268→        # Use indexed lookups to get items waiting for this symbol
   269→        # This avoids the expensive grep operations with isa checks
   270→        my @waiting_for_lhs = $chart->items_waiting_for($lhs, $completed_item->start_pos);
   271→        my @leo_waiting = $chart->leo_items_waiting_for($lhs, $completed_item->start_pos);
   272→
   273→  # Check for deterministic reduction (only if no Leo items waiting)
   274→  # Leo items are only for deterministic right-recursive chains where:
   275→  # 1. Only one item is waiting for this LHS
   276→  # 2. The waiting item will be complete after this reduction
   277→  # 3. The rule is right-recursive
   278→  #
   279→  # NOTE: Joop Leo's second optimization for left-recursion could be implemented
   280→  # here, but performance testing shows left-recursion is already faster than
   281→  # right-recursion in our Earley implementation, so it's not needed.
   282→        if (   @waiting_for_lhs == 1
   283→            && @leo_waiting == 0
   284→            && $waiting_for_lhs[0]->rule->is_right_recursive
   285→            && $waiting_for_lhs[0]->dot_pos ==
   286→            scalar( $waiting_for_lhs[0]->rule->rhs->@* ) - 1 )
   287→        {
   288→            my $waiting_item = $waiting_for_lhs[0];
   289→
   290→            # Use completed item's end position
   291→            my $leo = Chalk::LeoItem->new(
   292→                symbol    => $lhs,
   293→                start_pos => $waiting_item->start_pos,
   294→                end_pos   => $completed_item->end_pos,
   295→                top_item  => $waiting_item,
   296→            );
   297→
   298→            my $waiting_element = $chart->get_element($waiting_item);
   299→            next unless $waiting_element;
   300→            my $combined_element = $waiting_element * $completed_element;
   301→            $chart->add_element( $leo, $combined_element );
   302→            push( @$agenda, $leo );
   303→            return;    # Skip normal completion
   304→        }
   305→
   306→        # Normal completion for regular items
   307→        for my $waiting_item (@waiting_for_lhs) {
   308→
   309→            my $waiting_element = $chart->get_element($waiting_item);
   310→            next unless $waiting_element;
   311→
   312→            # Semiring multiplication ⊗ combines sequential components
   313→            my $combined_element = $waiting_element * $completed_element;
   314→
   315→            my $new_item = Chalk::EarleyItem->new(
   316→                start_pos => $waiting_item->start_pos,
   317→                rule      => $waiting_item->rule,
   318→                dot_pos   => $waiting_item->dot_pos + 1,
   319→                end_pos   => $completed_item->end_pos
   320→            );
   321→
   322→            # Only add if not already in chart
   323→            unless ( $chart->has_item($new_item) ) {
   324→                $chart->add_element( $new_item, $combined_element );
   325→                push( @$agenda, $new_item );
   326→            }
   327→        }
   328→
   329→        # Handle Leo items waiting for this completion
   330→        for my $leo_item (@leo_waiting) {
   331→
   332→            # Unpack the Leo chain to get the original waiting item
   333→            my $current = $leo_item->top_item;
   334→            while ( $current isa Chalk::LeoItem ) {
   335→                $current = $current->top_item;
   336→            }
   337→
   338→            # Now $current is the original EarleyItem at the bottom of the chain
   339→            # Complete it with the current completed item
   340→            my $waiting_element = $chart->get_element($leo_item);
   341→            next unless $waiting_element;
   342→            my $combined_element = $waiting_element * $completed_element;
   343→
   344→            my $new_item = Chalk::EarleyItem->new(
   345→                start_pos => $current->start_pos,
   346→                rule      => $current->rule,
   347→                dot_pos   => $current->dot_pos + 1,
   348→                end_pos   => $completed_item->end_pos
   349→            );
   350→
   351→            # Only add if not already in chart
   352→            unless ( $chart->has_item($new_item) ) {
   353→                $chart->add_element( $new_item, $combined_element );
   354→                push( @$agenda, $new_item );
   355→            }
   356→        }
   357→    }
   358→
   359→    method predict( $item, $nonterminal, $chart, $agenda ) {
   360→        my $pos = $item->end_pos;
   361→
   362→# Check if we've already predicted this nonterminal from this rule at this position
   363→# Multiple rules can predict the same nonterminal, so we track by rule origin
   364→        return if $chart->has_predicted( $nonterminal, $pos, $item->rule->id );
   365→        $chart->mark_predicted( $nonterminal, $pos, $item->rule->id );
   366→
   367→        for my $rule ( $grammar->rules_for($nonterminal) ) {
   368→            my $predicted_item = Chalk::EarleyItem->new(
   369→                start_pos => $pos,
   370→                rule      => $rule,
   371→                dot_pos   => 0,
   372→                end_pos   => $pos
   373→            );
   374→
   375→            # Only add if not already in chart
   376→            unless ( $chart->has_item($predicted_item) ) {
   377→                my $rule_element = $semiring->init_element_from_rule($rule, $pos, $pos);
   378→                $chart->add_element( $predicted_item, $rule_element );
   379→                push( @$agenda, $predicted_item );
   380→            }
   381→        }
   382→
   383→        # Aycock-Horspool optimization: if the nonterminal is nullable,
   384→        # we can also advance the dot past it immediately
   385→        if ( $grammar->is_nullable($nonterminal) ) {
   386→            my $advanced_item = Chalk::EarleyItem->new(
   387→                start_pos => $item->start_pos,
   388→                rule      => $item->rule,
   389→                dot_pos   => $item->dot_pos + 1,
   390→                end_pos   => $item->end_pos
   391→            );
   392→
   393→            # Only add if not already present
   394→            unless ( $chart->has_item($advanced_item) ) {
   395→                my $current_element = $chart->get_element($item);
   396→                if ($current_element) {
   397→                    $chart->add_element( $advanced_item, $current_element );
   398→                    push( @$agenda, $advanced_item );
   399→                }
   400→            }
   401→        }
   402→    }
   403→
   404→    method scan( $item, $element, $chart, $pos, $match_length ) {
   405→        my $scanned_item = Chalk::EarleyItem->new(
   406→            start_pos => $item->start_pos,
   407→            rule      => $item->rule,
   408→            dot_pos   => $item->dot_pos + 1,
   409→            end_pos   => $pos + $match_length
   410→        );
   411→
   412→        # All semirings receive position updates during scan
   413→        # Semirings can choose to use or ignore positions based on their needs
   414→        my $scanned_element = $semiring->init_element_from_rule(
   415→            $item->rule,
   416→            $scanned_item->start_pos,
   417→            $scanned_item->end_pos
   418→        );
   419→
   420→        $chart->add_element( $scanned_item, $scanned_element );
   421→    }
   422→}
   423→
   424→1;
