    my $parser = Chalk::Parser->new(
        grammar   => $Chalk::Grammar::Perl::chalk_grammar,
        semiring  => Chalk::Semiring::Boolean->new(),
    );

    # Multiplication binds tighter than addition
    ok($parser->parse_string('1 + 2 * 3'),
