    ok($parser->parse_string('$a | $b | $c'),
       'bitwise OR associates left');

    ok($parser->parse_string('$a & $b & $c'),
       'bitwise AND associates left');

    ok($parser->parse_string('$a ^ $b ^ $c'),
       'bitwise XOR associates left');

