plenv exec perl -e '
open my $fh, "<", "perl-tests/base/lex.t" or die $!;
my @lines = <$fh>;

# Test increasingly smaller chunks
for my $last_line (100, 200, 300, 400, 500, 520, 530, 535, 537, 538) {
    my $chunk = join "", @lines[0..$last_line-1];
    open my $out, ">", "/tmp/lex_chunk_$last_line.t" or die $!;
    print $out $chunk;
    close $out;
    print "Created chunk with $last_line lines (", length($chunk), " chars)\n";
}
'

for lines in 100 200 300 400 500 520 530 535 537 538; do
    echo -n "Testing $lines lines: "
    plenv exec perl -Ilib -MChalk::Parser -MChalk::Grammar::Perl -MChalk::Preprocessor::HeredocV2 -e '
    my $parser = Chalk::Parser->new(
        grammar => $Chalk::Grammar::Perl::chalk_grammar,
        preprocess => ["Chalk::Preprocessor::HeredocV2"]
    );
    my $input = do { local $/; open my $fh, "<", "/tmp/lex_chunk_'"$lines"'.t"; <$fh> };
    my $result = $parser->parse_string($input);
    print $result ? "SUCCESS" : "FAILED";
    ' 2>&1 | grep -v "🔍 PARSING"
done

plenv exec perl -Ilib -MChalk::Parser -MChalk::Grammar::Perl -MChalk::Preprocessor::HeredocV2 -e '
my $parser = Chalk::Parser->new(
    grammar => $Chalk::Grammar::Perl::chalk_grammar,
    preprocess => ["Chalk::Preprocessor::HeredocV2"]
);
my $input = do { local $/; open my $fh, "<", "/tmp/lex_chunk_200.t"; <$fh> };
print "Testing 200 lines (", length($input), " chars)...\n";
my $result = $parser->parse_string($input);
print $result ? "SUCCESS\n" : "FAILED\n";
'

