#!/usr/bin/env perl
# ABOUTME: Debug script to instrument parser and show active rules at failure point
# ABOUTME: Shows what the parser is trying to match when parsing stops
use 5.42.0;
use utf8;
use lib 'lib';
use Chalk::Parser;
use Chalk::Grammar::Perl;
use Chalk::Preprocessor::HeredocV2;

# Read the test file
my $input = do { local $/; open my $fh, "<", "perl-tests/base/lex.t"; <$fh> };

# Create parser
my $parser = Chalk::Parser->new(
    grammar => $Chalk::Grammar::Perl::chalk_grammar,
    preprocess => ['Chalk::Preprocessor::HeredocV2']
);

# Monkey-patch the process_position_string method to add debug output
{
    no warnings 'redefine';
    my $original = \&Chalk::Parser::process_position_string;

    *Chalk::Parser::process_position_string = sub {
        my ($self, $pos, $chart, $input_string) = @_;

        # Show debug info around division operator and failure point
        if (($pos >= 12100 && $pos <= 12115) || ($pos >= 12530 && $pos <= 12535) || ($pos >= 13200 && $pos <= 13220)) {
            my @agenda = $chart->items_ending_at($pos);
            print "\n=== Position $pos (char: ", substr($input_string, $pos, 1), ") ===\n";
            print "Active items: ", scalar(@agenda), "\n";

            for my $item (@agenda) {
                my $rule = $item->rule;
                my $lhs = $rule->lhs;
                my @rhs = $rule->rhs->@*;
                my $dot_pos = $item->dot_pos;
                my $start = $item->start_pos;

                # Build rule display with dot position
                my @display;
                for my $i (0..$#rhs) {
                    push @display, "•" if $i == $dot_pos;
                    push @display, $rhs[$i];
                }
                push @display, "•" if $dot_pos > $#rhs;

                printf "  [%d-%d] %s -> %s\n",
                    $start, $pos, $lhs, join(" ", @display);

                if (!$item->complete && $item->next_symbol) {
                    printf "    Waiting for: %s\n", $item->next_symbol;
                }
            }
        }

        $original->($self, $pos, $chart, $input_string);
    };
}

print "Parsing lex.t with debug output...\n";
my $result = $parser->parse_string($input);
print $result ? "SUCCESS\n" : "FAILED\n";

