#!/usr/bin/env perl
# ABOUTME: Simple test to see if grammar file parses successfully
# ABOUTME: Shows final parse position to identify where parsing stops
use 5.42.0;
use utf8;
use lib 'lib';
use Chalk::Parser;
use Chalk::Grammar::Perl;

my $input = do { local $/; open my $fh, "<", "lib/Chalk/Grammar/Perl.pm"; <$fh> };

my $parser = Chalk::Parser->new(
    grammar => $Chalk::Grammar::Perl::chalk_grammar,
    preprocess => ['Chalk::Preprocessor::HeredocV2']
);

print "Input length: ", length($input), " bytes\n";
my $result = $parser->parse_string($input);

if ($result) {
    print "SUCCESS - grammar file parses completely!\n";
} else {
    my $max_pos = $parser->max_position_reached;
    printf "FAILED at position %d (%.1f%% of %d)\n",
        $max_pos, ($max_pos / length($input)) * 100, length($input);

    # Show context around failure
    my $start = $max_pos - 50 > 0 ? $max_pos - 50 : 0;
    my $context = substr($input, $start, 100);
    $context =~ s/\n/\\n/g;
    print "Context: $context\n";
}

