#!/usr/bin/env perl
# ABOUTME: Debug script to show incomplete rules when parser times out
# ABOUTME: Shows which rules are being attempted at the failure point
use 5.42.0;
use utf8;
use lib 'lib';
use Chalk::Parser;
use Chalk::Grammar::Perl;

my $input = do { local $/; open my $fh, "<", "lib/Chalk/Grammar/Perl.pm"; <$fh> };
my $input_len = length($input);

print "Input length: $input_len bytes\n";
print "Expected failure around position ", $input_len - 6, "\n\n";

my $parser = Chalk::Parser->new(
    grammar => $Chalk::Grammar::Perl::chalk_grammar,
    preprocess => ['Chalk::Preprocessor::HeredocV2']
);

# Monkey-patch to show incomplete items at the failure point
{
    no warnings 'redefine';
    my $original = \&Chalk::Parser::process_position_string;
    my $max_pos_seen = 0;

    *Chalk::Parser::process_position_string = sub {
        my ($self, $pos, $chart, $input_string) = @_;

        $max_pos_seen = $pos if $pos > $max_pos_seen;

        # Show activity near the end
        my $near_end = $input_len - 20;
        if ($pos >= $near_end) {
            my @complete = grep { $_->complete } $chart->items_ending_at($pos);
            my @incomplete = grep { !$_->complete } $chart->items_at($pos);

            print "\n=== Position $pos ===\n";
            printf "Char: %s (0x%02x)\n",
                substr($input_string, $pos, 1) =~ /\n/ ? "\\n" : substr($input_string, $pos, 1),
                ord(substr($input_string, $pos, 1));
            print "Complete items: ", scalar(@complete), "\n";
            print "Incomplete items waiting: ", scalar(@incomplete), "\n\n";

            if (@incomplete && $pos == $max_pos_seen) {
                print "Top 20 incomplete items:\n";
                my $count = 0;
                for my $item (sort { $a->start_pos <=> $b->start_pos } @incomplete) {
                    last if $count++ >= 20;
                    my $rule = $item->rule;
                    my $lhs = $rule->lhs;
                    my $rhs = join(' ', map { ref($_) ? '<regex>' : $_ } @{$rule->rhs});
                    my $dot_pos = $item->dot_position;
                    my @parts = @{$rule->rhs};
                    my $progress = "$lhs → ";
                    for my $i (0..$#parts) {
                        $progress .= "• " if $i == $dot_pos;
                        $progress .= (ref($parts[$i]) ? '<regex>' : $parts[$i]) . " ";
                    }
                    $progress .= "•" if $dot_pos > $#parts;

                    printf "  [%d] %s\n", $item->start_pos, $progress;
                }
            }
        }

        $original->($self, $pos, $chart, $input_string);
    };
}

print "Parsing grammar file...\n";
my $result = $parser->parse_string($input);
print $result ? "SUCCESS\n" : "FAILED\n";

