#!/usr/bin/env perl
# ABOUTME: Shows which rules are incomplete when parsing stops
# ABOUTME: Uses reflection to inspect parser state at the end
use 5.42.0;
use utf8;
use lib 'lib';
use Chalk::Parser;
use Chalk::Grammar::Perl;

my $input = do { local $/; open my $fh, "<", "lib/Chalk/Grammar/Perl.pm"; <$fh> };
my $input_len = length($input);

print "Input length: $input_len bytes\n\n";

my $parser = Chalk::Parser->new(
    grammar => $Chalk::Grammar::Perl::chalk_grammar,
    preprocess => ['Chalk::Preprocessor::HeredocV2']
);

# Capture the chart for inspection
my $captured_chart;
{
    no warnings 'redefine';
    my $original = \&Chalk::Parser::parse_string;

    *Chalk::Parser::parse_string = sub {
        my ($self, $input_str) = @_;

        # Call original but capture chart
        package Chalk::Parser {
            use experimental 'class';
            method capture_parse($input_string) {
                for my $preprocessor_class ($self->{preprocess}->@*) {
                    next unless defined $preprocessor_class;
                    (my $file = $preprocessor_class) =~ s|::|/|g;
                    require "$file.pm";
                    my $preprocessor = $preprocessor_class->new(input => $input_string);
                    $preprocessor->transform();
                    $input_string = $preprocessor->output;
                }

                my $chart = Chalk::EarleyChart->new( semiring => $self->{semiring} );
                $captured_chart = $chart;

                my $start_symbol = $self->{grammar}->start_symbol;
                for my $rule ( $self->{grammar}->rules_for($start_symbol) ) {
                    my $start_item = Chalk::EarleyItem->new(
                        start_pos => 0, rule => $rule, dot_pos => 0, end_pos => 0,
                    );
                    my $start_element = $self->{semiring}->init_element_from_rule($rule, 0, 0);
                    $chart->add_element( $start_item, $start_element );
                }

                my $pos = 0;
                my $input_length = length($input_string);
                while ( $pos <= $input_length ) {
                    $self->process_position_string( $pos, $chart, $input_string );
                    ++$pos;
                }

                return $chart->goal_value( $self->{grammar}->start_symbol, $input_length );
            }
        }

        return $self->capture_parse($input_str);
    };
}

print "Parsing...\n";
my $result = $parser->parse_string($input);
print $result ? "SUCCESS\n" : "FAILED\n";

print "\n=== Analyzing incomplete items near end ===\n";

# Check positions near the end
for my $pos ($input_len - 10 .. $input_len) {
    my @items = $captured_chart->items_ending_at($pos);
    my @incomplete = grep { !$_->complete } @items;

    next unless @incomplete;

    print "\nPosition $pos: " . scalar(@incomplete) . " incomplete items\n";

    # Show top 10
    my $count = 0;
    for my $item (sort { $a->start_pos <=> $b->start_pos } @incomplete) {
        last if $count++ >= 10;
        my $rule = $item->rule;
        my $lhs = $rule->lhs;
        my @rhs = @{$rule->rhs};
        my $dot = $item->dot_position;

        my $next = $dot < @rhs ? ($rhs[$dot] =~ /^qr\// ? '<regex>' : $rhs[$dot]) : 'END';
        printf "  [%d] %s → ... • %s ...\n", $item->start_pos, $lhs, $next;
    }
}

