    # EARLY TERMINATION FOR BOOLEAN SEMIRING
    # If we're using Boolean semiring and we've already found ONE valid completion,
    # we don't need to explore ALL alternatives - just need to know parsing succeeds
    if ($semiring isa Chalk::Semiring::Boolean && @waiting_for_lhs > 0) {
