              my $combined = $semiring->add_id;
              for my $waiting_item (@$items) {
                  my $waiting_element = $chart->get_element($waiting_item);
                  next unless $waiting_element;
                  my $item_combined = $waiting_element * $completed_element;
                  $combined = $combined + $item_combined;
              }

              # Create Leo item using first item as representative
              # (start_pos doesn't matter for Leo key since we group by symbol+end)
              my $representative = $items->[0];
              my $leo = Chalk::LeoItem->new(
                  symbol    => $lhs,
                  start_pos => $representative->start_pos,
                  end_pos   => $completed_item->end_pos,
                  top_item  => $representative,
              );

              $chart->add_element( $leo, $combined );
              push( @$agenda, $leo );
              return;    # Skip normal completion
          }
      }

