        return if $chart->has_completed($completed_item);
        $chart->mark_completed($completed_item);

        my $lhs = $completed_item->rule->lhs;

        # Use indexed lookups to get items waiting for this symbol
        # This avoids the expensive grep operations with isa checks
        my @waiting_for_lhs = $chart->items_waiting_for($lhs, $completed_item->start_pos);
        my @leo_waiting = $chart->leo_items_waiting_for($lhs, $completed_item->start_pos);

  # Relaxed Leo optimization: Create Leo items for right-recursive rules
  # even when multiple items are waiting, as long as:
  # 1. No Leo items are already waiting (avoid nesting complexity)
  # 2. All waiting items are for the SAME right-recursive rule
  # 3. All waiting items are one position from completion
  #
  # This extends Leo beyond strictly deterministic cases while maintaining
  # correctness through semiring combination of multiple start positions.
        if (@leo_waiting == 0 && @waiting_for_lhs > 0) {
