                    printf("  [%d,%d] %s %s%s\n",
                        $item->start_pos, $item->end_pos, $rule_str, $complete, $next);
                }
                last;
            }
            $last_pos--;
        }

        print("=== END CHART DEBUG ===\n\n");
    }
}

