     1→#!/usr/bin/env perl
     2→# ABOUTME: Test that expression associativity is preserved after grammar simplification
     3→# ABOUTME: Validates left-associative and right-associative operators parse correctly
     4→use 5.42.0;
     5→use experimental qw(class builtin);
     6→use Test::More;
     7→use Chalk::Parser;
     8→use Chalk::Grammar::Perl;
     9→use Chalk::Semiring::Boolean;
    10→
    11→# Helper to validate expression against real Perl
    12→sub perl_accepts {
    13→    my ($expr) = @_;
    14→    my $result = system('perl', '-c', '-e', $expr, '2>/dev/null');
    15→    return $result == 0;
    16→}
    17→
    18→# Helper to validate expression is rejected by real Perl
    19→sub perl_rejects {
    20→    my ($expr) = @_;
    21→    return !perl_accepts($expr);
    22→}
    23→
    24→# Test right-associative operators (must associate right-to-left)
    25→subtest 'Right-associative operators' => sub {
    26→    my $parser = Chalk::Parser->new(
    27→        grammar   => $Chalk::Grammar::Perl::chalk_grammar,
    28→        semiring  => Chalk::Semiring::Boolean->new(),
    29→    );
    30→
    31→    # Assignment: $a = $b = 1 should parse as $a = ($b = 1)
    32→    ok($parser->parse_string('$a = $b = 1'),
    33→       'assignment associates right: $a = $b = 1');
    34→
    35→    ok($parser->parse_string('$x = $y = $z = 42'),
    36→       'chained assignment associates right: $x = $y = $z = 42');
    37→
    38→    # Power: 2 ** 3 ** 4 should parse as 2 ** (3 ** 4) = 2 ** 81 = big number
    39→    ok($parser->parse_string('2 ** 3 ** 4'),
    40→       'power associates right: 2 ** 3 ** 4');
    41→
    42→    ok($parser->parse_string('$x ** $y ** $z'),
    43→       'power with variables associates right');
    44→
    45→    # Ternary: a ? b : c ? d : e should parse as a ? b : (c ? d : e)
    46→    ok($parser->parse_string('$a ? $b : $c ? $d : $e'),
    47→       'ternary associates right: $a ? $b : $c ? $d : $e');
    48→
    49→    ok($parser->parse_string('1 ? 2 : 3 ? 4 : 5'),
    50→       'ternary with literals associates right');
    51→};
    52→
    53→# Test left-associative operators (must associate left-to-right)
    54→subtest 'Left-associative operators' => sub {
    55→    my $parser = Chalk::Parser->new(
    56→        grammar   => $Chalk::Grammar::Perl::chalk_grammar,
    57→        semiring  => Chalk::Semiring::Boolean->new(),
    58→    );
    59→
    60→    # Addition: 1 + 2 + 3 should parse as (1 + 2) + 3
    61→    ok($parser->parse_string('1 + 2 + 3'),
    62→       'addition associates left: 1 + 2 + 3');
    63→
    64→    ok($parser->parse_string('$a + $b + $c + $d'),
    65→       'chained addition associates left');
    66→
    67→    # Subtraction: 10 - 3 - 2 should parse as (10 - 3) - 2 = 5
    68→    ok($parser->parse_string('10 - 3 - 2'),
    69→       'subtraction associates left: 10 - 3 - 2');
    70→
    71→    # Multiplication: 2 * 3 * 4 should parse as (2 * 3) * 4
    72→    ok($parser->parse_string('2 * 3 * 4'),
    73→       'multiplication associates left: 2 * 3 * 4');
    74→
    75→    # Division: 24 / 4 / 2 should parse as (24 / 4) / 2 = 3
    76→    ok($parser->parse_string('24 / 4 / 2'),
    77→       'division associates left: 24 / 4 / 2');
    78→
    79→    # Logical AND: $a && $b && $c should parse as ($a && $b) && $c
    80→    ok($parser->parse_string('$a && $b && $c'),
    81→       'logical AND associates left: $a && $b && $c');
    82→
    83→    # Logical OR: $a || $b || $c should parse as ($a || $b) || $c
    84→    ok($parser->parse_string('$a || $b || $c'),
    85→       'logical OR associates left: $a || $b || $c');
    86→
    87→    # Bitwise operators
    88→    ok($parser->parse_string('$a | $b | $c'),
    89→       'bitwise OR associates left');
    90→
    91→    ok($parser->parse_string('$a & $b & $c'),
    92→       'bitwise AND associates left');
    93→
    94→    ok($parser->parse_string('$a ^ $b ^ $c'),
    95→       'bitwise XOR associates left');
    96→
    97→    # Shift operators
    98→    ok($parser->parse_string('$a << 1 << 2'),
    99→       'left shift associates left');
   100→
   101→    ok($parser->parse_string('$a >> 1 >> 2'),
   102→       'right shift associates left');
   103→
   104→    # String concatenation
   105→    ok($parser->parse_string('"a" . "b" . "c"'),
   106→       'string concatenation associates left');
   107→
   108→    # Comparison operators (non-associative in Perl, but should parse)
   109→    ok($parser->parse_string('$a == $b'),
   110→       'equality parses');
   111→
   112→    ok($parser->parse_string('$a < $b'),
   113→       'less-than parses');
   114→};
   115→
   116→# Test precedence (ensure nesting is preserved)
   117→subtest 'Operator precedence' => sub {
   118→    my $parser = Chalk::Parser->new(
   119→        grammar   => $Chalk::Grammar::Perl::chalk_grammar,
   120→        semiring  => Chalk::Semiring::Boolean->new(),
   121→    );
   122→
   123→    # Multiplication binds tighter than addition
   124→    ok($parser->parse_string('1 + 2 * 3'),
   125→       'precedence: 1 + 2 * 3 parses as 1 + (2 * 3)');
   126→
   127→    # Power binds tighter than multiplication
   128→    ok($parser->parse_string('2 * 3 ** 4'),
   129→       'precedence: 2 * 3 ** 4 parses as 2 * (3 ** 4)');
   130→
   131→    # Logical AND binds tighter than logical OR
   132→    ok($parser->parse_string('$a || $b && $c'),
   133→       'precedence: $a || $b && $c parses as $a || ($b && $c)');
   134→
   135→    # Assignment has lowest precedence (except comma)
   136→    ok($parser->parse_string('$a = $b + $c'),
   137→       'precedence: $a = $b + $c parses as $a = ($b + $c)');
   138→
   139→    ok($parser->parse_string('$a = $b && $c'),
   140→       'precedence: $a = $b && $c parses as $a = ($b && $c)');
   141→
   142→    # Complex mixed expression
   143→    ok($parser->parse_string('$a = $b + $c * $d ** $e'),
   144→       'complex precedence: $a = $b + $c * $d ** $e');
   145→};
   146→
   147→# Test that named operators work correctly
   148→subtest 'Named operators (or, and, not)' => sub {
   149→    my $parser = Chalk::Parser->new(
   150→        grammar   => $Chalk::Grammar::Perl::chalk_grammar,
   151→        semiring  => Chalk::Semiring::Boolean->new(),
   152→    );
   153→
   154→    ok($parser->parse_string('$a or $b or $c'),
   155→       'named or associates left');
   156→
   157→    ok($parser->parse_string('$a and $b and $c'),
   158→       'named and associates left');
   159→
   160→    ok($parser->parse_string('not $a'),
   161→       'named not parses');
   162→
   163→    # Named operators have very low precedence
   164→    ok($parser->parse_string('$a = $b or $c'),
   165→       'named or has lower precedence than assignment');
   166→};
   167→
   168→# Test range operator
   169→subtest 'Range operator' => sub {
   170→    my $parser = Chalk::Parser->new(
   171→        grammar   => $Chalk::Grammar::Perl::chalk_grammar,
   172→        semiring  => Chalk::Semiring::Boolean->new(),
   173→    );
   174→
   175→    ok($parser->parse_string('1 .. 10'),
   176→       'range: 1 .. 10');
   177→
   178→    ok($parser->parse_string('$a .. $b'),
   179→       'range with variables');
   180→
   181→    # Range is non-associative - chained range is a syntax error in Perl
   182→    # We don't test for it because it should fail
   183→};
   184→
   185→# Test comma operator
   186→subtest 'Comma operator' => sub {
   187→    my $parser = Chalk::Parser->new(
