#!/usr/bin/env perl
# ABOUTME: Convert grammar array initialization to push statements for binary search
# ABOUTME: Handles multi-line array references correctly
use 5.42.0;
use experimental qw(builtin);

# Read the grammar file
my $file = 'lib/Chalk/Grammar/Perl.pm';
open my $fh, '<', $file or die "Can't open $file: $!";
my $content = do { local $/; <$fh> };
close $fh;

# Find the array initialization
if ($content =~ /my \@grammar_rules = \((.*?)\n\);/s) {
    my $rules_section = $1;

    # Split into individual rules - each starts with [ and we need to find matching ]
    my @rules;
    my $current_rule = '';
    my $bracket_depth = 0;

    for my $line (split /\n/, $rules_section) {
        # Track bracket depth
        my $open_count = () = $line =~ /\[/g;
        my $close_count = () = $line =~ /\]/g;

        if ($line =~ /^\s*\[/ && $bracket_depth == 0) {
            # Start of new rule
            $current_rule = $line;
            $bracket_depth += $open_count - $close_count;
        } elsif ($bracket_depth > 0) {
            # Continuation of current rule
            $current_rule .= "\n$line";
            $bracket_depth += $open_count - $close_count;
        }

        # If brackets balanced, we have a complete rule
        if ($bracket_depth == 0 && $current_rule ne '') {
            # Remove trailing comma if present
            $current_rule =~ s/,\s*$//;
            push @rules, $current_rule;
            $current_rule = '';
        }
    }

    # Generate push statements
    my $push_statements = join("\n", map { "push \@grammar_rules, $_;" } @rules);

    # Replace in content
    $content =~ s/my \@grammar_rules = \(.*?\n\);/my \@grammar_rules;\n\n$push_statements/s;

    # Write output
    open my $out, '>', $file or die "Can't write $file: $!";
    print $out $content;
    close $out;

    say "Converted " . scalar(@rules) . " array elements to push statements";
} else {
    die "Could not find grammar_rules array in expected format";
}

