#!/usr/bin/env perl
use 5.42.0;
use lib 'lib';

BEGIN {
    # Intercept the build_grammar call to see what's being passed
    no warnings 'redefine';
    my $original = \&Chalk::Grammar::build_grammar;
    *Chalk::Grammar::build_grammar = sub {
        my ($class, %args) = @_;
        say "build_grammar called with:";
        say "  auto_insert: ", join(', ', $args{auto_insert}->@*) if $args{auto_insert};
        say "  rules type: ", ref($args{rules});
        say "  rules count: ", scalar($args{rules}->@*) if ref($args{rules}) eq 'ARRAY';
        say "  first rule: ", $args{rules}->[0] if ref($args{rules}) eq 'ARRAY' && $args{rules}->[0];
        say "  first rule type: ", ref($args{rules}->[0]) if ref($args{rules}) eq 'ARRAY' && $args{rules}->[0];

        # Call original
        return $original->($class, %args);
    };
}

require Chalk::Grammar::Perl;

say "Module loaded successfully";

